import assert from 'node:assert/strict';
import { after, before, describe, it } from 'node:test';
import { api, startTestServer, type TestServer } from './helpers.ts';

const CARRIERS = ['ATP', 'DHL', 'DPD', 'GLS', 'UPS'] as const;

describe('GET /shipments on a large dataset (5k)', () => {
  let srv: TestServer;

  before(async () => {
    srv = await startTestServer();
    for (let i = 0; i < 5000; i++) {
      const s = srv.store.addShipment(
        {
          trackingNumber: `PERF${i}`,
          carrier: CARRIERS[i % 5],
          serviceLevel: 'standard',
          recipient: { name: 'x', street: 'x', zip: '1010', city: 'Wien', country: 'AT' },
        } as any,
        new Date(Date.UTC(2026, 10, 2) + i * 1000),
      );
      srv.store.addEvent(s.id, 'picked_up', { at: '2026-11-03T08:00:00.000Z' });
    }
  });

  after(async () => {
    await srv.close();
  });

  it('only returns (and computes ETAs for) `limit` items, within a time budget', async () => {
    const start = performance.now();
    const res = await api(srv.url, 'GET', '/shipments?limit=500');
    const ms = performance.now() - start;
    assert.equal(res.status, 200);
    assert.equal(res.body.count, 500);
    assert.ok(ms < 500, `list took ${ms.toFixed(0)} ms`);
  });

  it('never serves a stale ETA after a new exception event', async () => {
    const first = (await api(srv.url, 'GET', '/shipments?limit=1')).body.items[0];
    srv.store.addEvent(first.id, 'exception', { at: '2026-11-04T08:00:00.000Z' });
    const again = (await api(srv.url, 'GET', '/shipments?limit=1')).body.items[0];
    assert.equal(again.id, first.id);
    assert.ok(again.eta > first.eta, `${again.eta} should be later than ${first.eta}`);
  });
});
EOF
